DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261127094045_Initial') THEN
    CREATE TABLE "Admins" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Email" text NOT NULL,
        "PasswordHash" text NOT NULL,
        CONSTRAINT "PK_Admins" PRIMARY KEY ("Id")
